// Single source of truth for Pro access.
// ── iOS BETA IAP BYPASS (temporary; remove when StoreKit IAP lands) ──────────
// iOS has no App Store IAP wired yet (the RevenueCat key is Android-only), and
// Apple rejects builds that gate features behind a purchase path that does not
// work. For the TestFlight beta this unlocks everything on the native iOS shell
// so review never meets a dead purchase button and friends & family see the
// whole app. Scoped to isIOS() && isCapacitor(), so it does NOT affect Android,
// desktop, or the iOS PWA — only the native iOS build.
//
// Before an iOS SUBMISSION, one of these has to be true:
//   · StoreKit IAP is implemented and the purchase path actually works, or
//   · this bypass is still in place so nothing is gated behind a dead button.
// Android is unaffected either way; RevenueCat works there.
function _iosBetaUnlock() {
  try { return isIOS() && isCapacitor(); } catch (e) { return false; }
}
function isPro() { return progState.hasPro === true || _iosBetaUnlock(); }

